package com.indianservers.AIbiology.data

internal data class LessonAreaProfile(
    val foundation: String,
    val example: String,
    val importance: String,
    val advanced: String
)

/**
 * Reviewed foundations used only when a concept does not yet have a longer
 * concept-specific entry. They keep fallback lessons biologically meaningful
 * and prevent the same generic paragraph from appearing in unrelated fields.
 */
internal object LessonAreaProfiles {
    private fun p(foundation: String, example: String, importance: String, advanced: String) =
        LessonAreaProfile(foundation, example, importance, advanced)

    private val profiles = mapOf(
        "Introduction to Biology" to p("Biology studies living systems through observation, measurement, testable explanations, and evidence.", "A controlled seedling study changes light while keeping water and plant type constant.", "It supports sound decisions about health, food, nature, and scientific claims.", "experimental design, uncertainty, statistics, replication, ethics, and alternative explanations"),
        "Biomolecules" to p("Water, carbohydrates, lipids, proteins, nucleic acids, vitamins, and minerals support cell structure and reactions.", "Heating egg white changes protein structure, while starch can be broken into sugars.", "Nutrition, membranes, enzymes, energy transfer, and genetic information depend on molecular properties.", "bonding, three-dimensional structure, thermodynamics, metabolism, and molecular analysis"),
        "Cell Biology" to p("Cells are the basic units of life; membranes, organelles, genetic information, and chemical reactions act as one regulated system.", "Muscle cells contain many mitochondria because contraction requires a steady ATP supply.", "Growth, repair, infection, inherited disorders, and cancer begin with cell processes.", "organelle dynamics, membrane traffic, signalling, cytoskeletal forces, gene control, and cell fate"),
        "Cell Division" to p("Cells copy DNA and separate chromosomes; mitosis and meiosis produce cells for different biological roles.", "Skin repair uses mitosis, while sperm and egg production uses meiosis.", "Division enables growth and reproduction, while errors can cause chromosome disorders or cancer.", "checkpoints, cyclins, spindle mechanics, recombination, segregation, and genome stability"),
        "Biological Membranes & Transport" to p("Selective membranes control water, ions, gases, nutrients, and waste by passive and energy-dependent transport.", "Oxygen diffuses from lung air sacs into blood, while ion pumps maintain gradients.", "Cells must control composition, volume, electrical activity, and communication.", "electrochemical gradients, permeability, channel gating, kinetics, osmotic pressure, and voltage"),
        "Enzymes" to p("Enzymes speed reactions by lowering activation energy and binding particular substrates without being consumed overall.", "Salivary amylase begins starch digestion, and catalase removes hydrogen peroxide.", "Nearly every controlled cell reaction depends on enzyme activity.", "catalytic mechanisms, induced fit, cofactors, inhibition, regulation, and kinetics"),
        "Bioenergetics" to p("Respiration and photosynthesis transform energy, often coupling electron transfer and proton gradients to ATP production.", "Working muscles increase respiration, while leaves store light energy in carbon compounds.", "Energy transformation supports growth, movement, food webs, and the carbon cycle.", "redox chemistry, chemiosmosis, metabolic control, carbon fixation, efficiency, and adaptation"),
        "Molecular Biology" to p("DNA stores information, RNA helps express and regulate it, and ribosomes use coded information to build proteins.", "An insulin-producing cell activates genes needed to make and release insulin.", "Gene expression explains cell identity, development, inheritance, and many diseases.", "replication fidelity, transcription, RNA processing, translation, chromatin, and regulation"),
        "Genetics" to p("Genetics studies inherited DNA variation and how genes and environments contribute to traits.", "ABO blood groups show multiple alleles and codominance, while height is polygenic.", "It supports risk assessment, breeding, evolutionary study, and precision medicine.", "linkage, recombination, gene interaction, penetrance, quantitative traits, and population forces"),
        "Biotechnology" to p("Biotechnology uses cells, biological molecules, and genetic information to measure, modify, or produce useful systems.", "PCR copies a DNA region, and engineered bacteria can produce human insulin.", "It supports diagnostics, medicines, agriculture, research, and environmental solutions.", "molecular design, delivery, specificity, off-target effects, validation, biosafety, and ethics"),
        "Evolution" to p("Populations change across generations through mutation, selection, drift, gene flow, and recombination.", "Antibiotic use can increase the frequency of resistant bacteria.", "Evolution explains adaptation, biodiversity, common ancestry, and changing pathogens.", "allele-frequency change, fitness trade-offs, speciation, phylogenetics, and historical constraint"),
        "Diversity of Life (Taxonomy)" to p("Taxonomy names and groups organisms, while phylogeny tests hypotheses of common ancestry.", "Whales are mammals despite living in water, and mushrooms are fungi rather than plants.", "Shared names and tested relationships support identification, medicine, ecology, and conservation.", "molecular phylogenetics, tree uncertainty, species concepts, character evolution, and classification"),
        "Microbiology" to p("Microbiology studies microscopic organisms and acellular agents, including bacteria, archaea, fungi, protists, and viruses.", "Gut bacteria interact with digestion, yeast raises bread, and soil microbes recycle nutrients.", "Microbes shape health, food, industry, ecosystems, and global chemical cycles.", "microbial genomes, metabolism, host interaction, biofilms, communities, and resistance"),
        "Plant Biology" to p("Plants capture light, exchange gases, transport water and sugars, sense conditions, grow, and reproduce.", "Roots absorb water, xylem transports it, and leaves lose some water by transpiration.", "Plants provide food, oxygen, materials, habitats, and climate regulation.", "developmental signals, hormones, transport physics, carbon fixation, stress, and reproductive timing"),
        "Animal Biology" to p("Animal cells form tissues and organ systems within body plans shaped by development and evolution.", "Jellyfish show radial symmetry, while humans show bilateral symmetry.", "Comparisons reveal how animals function, develop, behave, and adapt.", "developmental patterning, biomechanics, physiology, neural control, behaviour, and evolution"),
        "Human Anatomy" to p("Anatomy describes structures using standard directions, planes, cavities, tissues, organs, and systems.", "The heart lies in the thoracic cavity between the lungs.", "Precise structural knowledge supports imaging, diagnosis, surgery, and rehabilitation.", "three-dimensional relationships, histology, variation, imaging, and clinical landmarks"),
        "Human Physiology" to p("Physiology explains how organ systems exchange materials and signals while maintaining internal conditions.", "Heart rate rises during exercise and sweating helps limit body-temperature rise.", "Body functions, symptoms, health choices, and treatments depend on system interactions.", "feedback control, transport, electrophysiology, endocrine signalling, integration, and pathophysiology"),
        "Immunology" to p("Innate defences act quickly; adaptive cells recognize specific antigens and can form memory.", "Vaccination prepares memory cells to respond faster to later pathogen exposure.", "Immunity affects infection, allergy, autoimmunity, transplantation, vaccines, and cancer treatment.", "antigen presentation, clonal selection, receptor diversity, tolerance, cytokines, and immunotherapy"),
        "Developmental Biology" to p("Development transforms a fertilized cell into an organism through division, movement, signalling, and specialization.", "Gastrulation moves cells into layers that later contribute to different tissues.", "It explains pregnancy, congenital differences, regeneration, and stem-cell behaviour.", "morphogens, gene networks, mechanics, pattern formation, organogenesis, and regeneration"),
        "Histology" to p("Histology studies how cells and extracellular material are organized into tissues and organs.", "Thin lung tissue supports gas exchange, while intestinal folds increase absorptive area.", "Microscopic architecture connects normal function with injury and disease.", "molecular markers, spatial organization, extracellular matrix, renewal, pathology, and imaging"),
        "Ecology" to p("Ecology studies organisms and environments; energy flows through systems while matter cycles.", "Removing a predator can change prey, vegetation, and nutrient movement.", "Ecology supports biodiversity, food, water, climate resilience, and conservation.", "population dynamics, networks, succession, biogeochemical cycles, resilience, scale, and uncertainty"),
        "Environmental Biology" to p("Environmental biology examines how pollution, resource use, and restoration affect living systems.", "Excess fertilizer can promote algal growth and low oxygen in water.", "Clean air, water, soil, and functioning ecosystems are essential for health.", "dose-response, contaminant fate, bioaccumulation, life-cycle assessment, and adaptive restoration"),
        "Ethology (Animal Behaviour)" to p("Behaviour emerges from inherited tendencies, learning, physiology, environment, and evolutionary history.", "Bees communicate food location through patterned movements.", "Behaviour affects survival, reproduction, welfare, farming, and conservation.", "neural mechanisms, development, communication, trade-offs, social evolution, and fitness"),
        "Marine Biology" to p("Marine life is shaped by light, depth, pressure, temperature, salinity, currents, nutrients, and oxygen.", "Phytoplankton photosynthesize near the surface, while deep-sea species live without sunlight.", "Oceans regulate climate, supply food and oxygen, and contain major biodiversity.", "ocean biogeochemistry, food webs, adaptation, population assessment, and climate effects"),
        "Agricultural Biology" to p("Agriculture applies plant, animal, microbial, soil, genetic, and ecological knowledge to production.", "Crop rotation can improve soil and interrupt some pest life cycles.", "Food production must balance yield, nutrition, farmer needs, and environmental protection.", "breeding, soil communities, integrated pest management, sensing, modelling, and sustainability"),
        "Medical Biology" to p("Medical biology connects altered molecules, cells, tissues, microbes, genes, and systems with disease.", "A glucose test contributes evidence when evaluating diabetes.", "Accurate mechanisms and measurements support prevention, diagnosis, prognosis, and treatment.", "pathogenesis, biomarkers, pharmacology, clinical genetics, epidemiology, and evidence quality"),
        "Parasitology" to p("Parasites obtain resources from hosts and often pass through specialized stages, hosts, or vectors.", "Malaria parasites develop in both mosquito and human hosts.", "Parasites affect people, animals, crops, ecosystems, and food security.", "host-parasite coevolution, immune evasion, vectors, drug resistance, surveillance, and One Health"),
        "Virology" to p("Viruses contain a DNA or RNA genome in a protective structure and reproduce using host cells.", "Bacteriophages infect bacteria, while influenza viruses infect respiratory cells.", "Viruses affect health, agriculture, evolution, and biotechnology.", "entry, genome replication, assembly, host responses, evolution, transmission, and antivirals"),
        "Mycology" to p("Fungi are absorptive eukaryotes including yeasts, moulds, and mushrooms; their cell walls commonly contain chitin.", "Mycorrhizal fungi aid many roots, while yeast performs fermentation.", "Fungi recycle nutrients, support plants, make products, and can cause disease.", "fungal phylogeny, symbiosis, secondary metabolism, host invasion, and antifungal targets"),
        "Entomology" to p("Insects are arthropods with three main body regions, six legs, and a chitinous exoskeleton.", "Bees pollinate flowers, while mosquitoes can transmit pathogens.", "Insects support ecosystems and economies but may damage crops or spread disease.", "metamorphosis, sensory biology, flight, social systems, vector biology, and pest management"),
        "Zoology" to p("Zoology compares animal diversity, structure, function, development, ecology, and relationships.", "Sponges filter water, earthworms are segmented, and mammals produce milk.", "Animal knowledge supports conservation, medicine, farming, fisheries, and evolution.", "phylogenomics, comparative physiology, development, biomechanics, adaptation, and diversification"),
        "Botany" to p("Botany studies plant diversity, evolution, classification, uses, and relationships with people.", "Mosses lack true vascular tissue, ferns disperse spores, and fruits enclose angiosperm seeds.", "Plants underpin food, materials, medicine, culture, and ecosystems.", "plant phylogenomics, trait evolution, biogeography, economic uses, and ethical ethnobotany"),
        "Biochemistry" to p("Biochemistry studies life's reactions, pathways, energy transfers, and molecular regulation.", "Glycolysis begins glucose breakdown, while insulin coordinates glucose use and storage.", "Metabolism explains nutrition, exercise, inherited disorders, tests, and drug action.", "enzyme regulation, redox balance, pathway integration, flux, compartments, and hormonal control"),
        "Biophysics" to p("Biophysics applies forces, energy, electricity, fluids, and imaging principles to living systems.", "Ion movement produces nerve voltage, and vessel radius strongly affects flow resistance.", "Physical rules explain movement, circulation, sensation, scans, and molecular behaviour.", "transport equations, mechanics, electrophysiology, thermodynamics, detection, and imaging trade-offs"),
        "Systems Biology" to p("Systems biology studies interacting components as networks with feedback, dynamics, and emergent behaviour.", "Several hormones and organs form a network that regulates blood glucose.", "Complex traits and diseases rarely arise from one isolated component.", "network structure, dynamic models, parameter estimation, multi-scale integration, and validation"),
        "Bioinformatics" to p("Bioinformatics uses algorithms, statistics, databases, and computing to analyse biological data.", "Sequence alignment helps identify related DNA, RNA, or protein sequences.", "Large genomic datasets cannot be interpreted reliably by inspection alone.", "algorithms, uncertainty, multiple testing, reproducibility, machine learning, and data governance"),
        "Neuroscience" to p("Neurons, glial cells, synapses, and circuits produce sensation, action, learning, and behaviour.", "Sensory neurons detect heat and motor pathways help withdraw the hand.", "Neuroscience supports learning, pain care, rehabilitation, and brain health.", "ion channels, synaptic transmission, plasticity, circuit computation, systems control, and behaviour"),
        "Endocrinology" to p("Hormone effects depend on concentration, timing, receptors, target tissues, and feedback.", "Insulin helps lower elevated blood glucose after a meal.", "Hormones coordinate growth, metabolism, stress, reproduction, sleep, and water balance.", "receptor signalling, pulsatile secretion, endocrine axes, feedback, cross-talk, and metabolism"),
        "Reproductive Biology" to p("Reproductive biology covers gametes, fertilization, pregnancy, birth, fertility care, and contraception.", "Meiosis produces sperm or eggs with one chromosome set.", "Accurate knowledge supports health, consent, fertility decisions, and pregnancy care.", "gamete biology, endocrine feedback, implantation, maternal-fetal physiology, assisted reproduction, and ethics"),
        "Genomics & Omics" to p("Omics methods measure many DNA sequences, RNAs, proteins, metabolites, microbes, or cells at once.", "RNA sequencing compares active genes in healthy and diseased tissue.", "System-wide data can reveal cell types, pathways, biomarkers, and treatment responses.", "sampling, normalization, batch effects, high-dimensional statistics, integration, and validation"),
        "Cancer Biology" to p("Cancer develops when altered cells escape controls on growth, survival, genome maintenance, and tissue boundaries.", "A biopsy reveals architecture, while molecular tests can identify a treatment target.", "Mechanistic knowledge supports prevention, diagnosis, treatment, and resistance management.", "driver mutations, tumour suppressors, microenvironment, clonal evolution, metastasis, and immunity"),
        "Public Health Biology" to p("Public health prevents health problems across populations using surveillance, epidemiology, and community action.", "Vaccination, safe water, sanitation, and surveillance prevent illness at scale.", "Population health depends on biology, behaviour, environment, access, and social conditions.", "study design, bias, confounding, risk, screening, prevention, implementation, equity, and global health"),
        "Laboratory Biology" to p("Laboratory methods make biological structures and processes observable, measurable, separable, or testable.", "Microscopy shows cells, centrifugation separates components, and ELISA detects targets.", "Diagnosis and research depend on safe methods, controls, records, and reproducibility.", "detection limits, calibration, specificity, sensitivity, preparation, quality control, and biosafety"),
        "Advanced Biology (PG / Research)" to p("Advanced biology integrates molecular, cellular, organismal, computational, medical, and evolutionary evidence.", "Structural data can show drug-protein binding while models predict system effects.", "Research connects foundations to difficult questions in health, technology, evolution, and astrobiology.", "multi-scale mechanisms, quantitative models, causal inference, uncertainty, reproducibility, ethics, and translation"),
        "Grade 6 Biology" to p("Grade 6 biology begins with careful observation of living things, food, life cycles, and natural resources.", "A learner can compare local leaves, test food, germinate seeds, and record biodiversity.", "These ideas build healthy habits, curiosity, and care for living systems.", "fair tests, patterns, evidence, connected resources, and responsible choices"),
        "Grade 7 Biology" to p("Grade 7 biology explains adolescence and the life processes that keep animals and plants alive.", "A learner can trace digestion, model breathing, and test the requirements for photosynthesis.", "These ideas connect personal health with the movement of matter and energy in organisms.", "organ systems, gas exchange, transport tissues, controlled experiments, and healthy decisions")
    )

    fun forArea(title: String): LessonAreaProfile =
        requireNotNull(profiles[title]) { "Missing lesson profile for $title" }
}
